static inline bool s_task_stack_is_sane_when_cache_frozen(void)
{
    const void *sp = (const void *)esp_cpu_get_sp();

    return esp_ptr_in_dram(sp)
#if CONFIG_ESP_SYSTEM_ALLOW_RTC_FAST_MEM_AS_HEAP
           || esp_ptr_in_rtc_dram_fast(sp)
#endif
           ;
}

void esp_cache_freeze_caches_disable_interrupts(void)
{
    assert(s_task_stack_is_sane_when_cache_frozen());
    esp_os_enter_critical_safe(&s_spinlock);

    /**
     * - disable non-iram interrupt on current core
     * - current core call cache freeze
     * - external access from other cores will hang on cache
     */
    esp_intr_noniram_disable();
    esp_cache_freeze_ext_mem_cache();
}

void esp_cache_unfreeze_caches_enable_interrupts(void)
{
    esp_cache_unfreeze_ext_mem_cache();
    esp_intr_noniram_enable();
    esp_os_exit_critical_safe(&s_spinlock);
}
#endif
        }
    }

#if !CONFIG_ESP_SYSTEM_SINGLE_CORE_MODE
    s_system_inited[core_id] = true;
#endif
}

#if !CONFIG_ESP_SYSTEM_SINGLE_CORE_MODE
static void  esp_startup_start_app_other_cores_default(void)
{
    while (1) {
        esp_rom_delay_us(UINT32_MAX);
    }
}

/* This function has to be in IRAM, as while it is running on CPU1, CPU0 may do some flash operations
 * (e.g. initialize the core dump), which means that cache will be disabled.
 */
static void ESP_SYSTEM_IRAM_ATTR start_cpu_other_cores_default(void)
{
    do_system_init_fn(ESP_SYSTEM_INIT_STAGE_SECONDARY);

    while (!s_system_full_inited) {
        esp_rom_delay_us(100);
    }

    esp_os_startup_start_app_other_cores();
}
#endif

static void do_core_init(void)
{
    do_system_init_fn(ESP_SYSTEM_INIT_STAGE_CORE);
}

static void do_secondary_init(void)
{
#ifndef __NuttX__
#if !CONFIG_ESP_SYSTEM_SINGLE_CORE_MODE
    // The port layer transferred control to this function with other cores 'paused',
    // resume execution so that cores might execute component initialization functions.
    startup_resume_other_cores();
#endif
#endif
    // Execute initialization functions esp_system_init_fn_t assigned to the main core. While
    // this is happening, all other cores are executing the initialization functions
    // assigned to them since they have been resumed already.
    do_system_init_fn(ESP_SYSTEM_INIT_STAGE_SECONDARY);

#ifndef __NuttX__
    // NuttX can't support this loop, since CPU1 is only started later on the start up sequence.
    // nx_smp_start() is called later, on nx_start() which is called after SYS_STARTUP_FN().
#if !CONFIG_ESP_SYSTEM_SINGLE_CORE_MODE
    // Wait for all cores to finish secondary init.
    volatile bool system_inited = false;

    while (!system_inited) {
        system_inited = true;
        for (int i = 0; i < SOC_CPU_CORES_NUM; i++) {
            system_inited &= s_system_inited[i];
        }
        esp_rom_delay_us(100);
    }
#endif
#endif  // __NuttX__
}

static void start_cpu0_default(void)
{
    extern void __libc_init_array(void);
    // Initialize core components and services.
    // Operations that needs the cache to be disabled have to be done here.
    do_core_init();

    // Execute constructors.
#ifdef CONFIG_COMPILER_CXX_EXCEPTIONS
    __do_global_ctors_1();
#endif

    __libc_init_array();

    /* ----------------------------------Separator-----------------------------
     * After this stage, other CPU start running with the cache, however the scheduler (and ipc service) is not available.
     * Don't touch the cache/MMU until the OS is up.
     */

    // Execute init functions of other components; blocks
    // until all cores finish (when !CONFIG_ESP_SYSTEM_SINGLE_CORE_MODE).
    do_secondary_init();

#if SOC_CPU_CORES_NUM > 1 && !CONFIG_ESP_SYSTEM_SINGLE_CORE_MODE
    s_system_full_inited = true;
#endif

#ifndef __NuttX__
    esp_startup_start_app();

    ESP_INFINITE_LOOP();
#endif
}

L1-8 的 7 个 Pattern **不来源于 nuttx-api-patterns.md**（那 52 个 pattern 全部是 CWE 映射的缺陷检测 pattern）。L1-8 Pattern 是独立定义的架构决策检测 pattern，编号前缀用 `DP-`（Design Philosophy）以示区分。

**检测矩阵**:

| Pattern | 检测方式 | 确定性特征 | Confidence | 工具辅助 |
|:--------|:---------|:-----------|:----------:|:--------:|
| DP-01 绕过抽象层 | LLM (调用链层次分析) | — | MEDIUM | ✗ |
| DP-02 跨层依赖 | LLM + Tool | `#include` 路径模式匹配 | HIGH | ✓ |
| DP-03 头文件泄漏 | LLM (public header 审查) | `include/` 目录下新增非 API 符号 | HIGH | ✗ |
| DP-04 缺少 static | Tool + LLM | cppcheck `unusedFunction` | HIGH | ✓ |
| DP-05 板级侵入 | LLM (#ifdef 位置分析) | `CONFIG_ARCH_*` / `CONFIG_BOARD_*` 在非 board/ 文件 | HIGH | ✗ |
| DP-06 影子状态 | LLM (状态语义重叠分析) | — | MEDIUM | ✗ |
| DP-07 重复造轮子 | LLM (NuttX 基础设施匹配) | — | MEDIUM | ✗ |

**分级总结**:

- **工具可辅助 (2/7)**: DP-02 (`#include` 路径 grep)、DP-04 (cppcheck)。这两个 pattern 可在 LLM 检测前/后用工具交叉验证，达到近 0.9 置信度。
- **确定性特征可检测 (4/7)**: DP-02/03/04/05 具备可 grep 的文本特征（路径、关键字、目录位置），HIGH confidence，接近工具级准确率。
- **纯 LLM 语义推理 (3/7)**: DP-01/06/07 依赖 LLM 对 NuttX 架构的语义理解，MEDIUM confidence，无工具可直接替代。

> **Confidence 来源**: L1-8 的 Confidence 不来自 nuttx-api-patterns.md（那是 L1-1~L1-7 的来源），而是基于各 DP-pattern 的检测信号强度独立评估——有确定性文本特征 → HIGH，纯语义推理 → MEDIUM。

